      {
        id: 'm-new-0608-d',
        text: 'A therapist says \'Remember, the tall one is correct\' to help the child select the correct stimulus.',
        isCorrect: false,
        explanation: 'A verbal hint is a verbal response prompt, not a within-stimulus prompt.'
      }
